package com.notesshared.model;
public class User{private int id,collegeId;private Integer courseId;private String name,email,passwordHash,role,approvalStatus;public int getId(){return id;}public void setId(int v){id=v;}public int getCollegeId(){return collegeId;}public void setCollegeId(int v){collegeId=v;}public Integer getCourseId(){return courseId;}public void setCourseId(Integer v){courseId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String v){passwordHash=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public String getApprovalStatus(){return approvalStatus;}public void setApprovalStatus(String v){approvalStatus=v;}}
